@startuml

class Organizer {
  + FirstName : string
  + LastName : string
  + Email : string
  + PostalAddress : string
  + PhoneNumber : string
  + Password : string
}

class Attendee {
  + FirstName : string
  + LastName : string
  + Email : string
  + Password : string
  + AttendanceStatus : string
}

class EventType {
  + Name : string
}

class Event {
  + StartDateTime : datetime
  + EndDateTime : datetime
  + Occasion : string
}

class Location {
  + Name : string
  + Address : string
}

class Task {
  + Description : string
  + Status : string
  + IsAssignedToAttendee : boolean
}

class EventTaskAssignment {
  + Task : Task
  + Attendee : Attendee
}

Organizer "1..*" -- "0..*" Event : organizes
Organizer "0..1" -- "0..*" Event : attends
Organizer "1" -- "0..*" EventType : creates
Event "0..*" -- "1" EventType : is of type
Event "0..*" -- "1" Location : at
Event "1" *-- "0..*" Task : has checklist
Task "0..*" -- "0..*" Attendee : is assigned to

@enduml

